import{_ as i,C as a,o as n,c as d,j as t,a as l,E as s,ah as h}from"./chunks/framework.Dmqp7bmQ.js";const b=JSON.parse('{"title":"Message templates","description":"","frontmatter":{},"headers":[],"relativePath":"templates.md","filePath":"templates.md"}'),m={name:"templates.md"};function p(c,e,g,f,u,w){const o=a("Mermaid"),r=a("AppDemo");return n(),d("div",null,[e[0]||(e[0]=t("h1",{id:"message-templates",tabindex:"-1"},[l("Message templates "),t("a",{class:"header-anchor",href:"#message-templates","aria-label":'Permalink to "Message templates"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Some rooms take structured messages as well as, or instead of, free text: a situation report, a contact report, a request for support. The admin designs each one as a form. Players pick a template in the room's composer, fill in its form and send it, and everyone in the room sees the message as a card with a label and a value for each field.",-1)),e[2]||(e[2]=t("p",null,"Templates follow the specification in the SRD's Annex A, built in Phase 4. Image and asset pickers are not built yet: they wait for the decision on how images are stored, and for the force assets of the planned map channel.",-1)),s(o,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20Admin%5B%22Admin%3A%20the%20design%20editor%22%5D%0A%20%20%20%20%20%20%20%20Builder%5B%22Builder%3A%20drag%20fields%20in%22%5D%0A%20%20%20%20%20%20%20%20Raw%5B%22Raw%20JSON%20Schema%20editor%22%5D%0A%20%20%20%20%20%20%20%20Preview%5B%22Live%20preview%3A%20the%20player's%20form%22%5D%0A%20%20%20%20%20%20%20%20Rooms%5B%22Room%20settings%3A%20free%20text%2C%20who%20may%20use%20what%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Server%5B%22XMPP%20server%22%5D%0A%20%20%20%20%20%20%20%20Store%5B(%22Templates%3A%20one%20item%20each%22)%5D%0A%20%20%20%20%20%20%20%20Config%5B(%22Each%20room's%20settings%22)%5D%0A%20%20%20%20%20%20%20%20Room%5B(%22The%20room's%20messages%22)%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Player%5B%22Player%20client%22%5D%0A%20%20%20%20%20%20%20%20Composer%5B%22Composer%3A%20template%20drop-down%20and%20form%22%5D%0A%20%20%20%20%20%20%20%20Check%5B%22Check%20against%20the%20template%22%5D%0A%20%20%20%20%20%20%20%20Card%5B%22Card%22%5D%0A%20%20%20%20end%0A%20%20%20%20Builder%20%26%20Raw%20--%3E%20Preview%0A%20%20%20%20Builder%20%26%20Raw%20--%3E%7Cpublish%7C%20Store%0A%20%20%20%20Rooms%20--%3E%7Cpublish%7C%20Config%0A%20%20%20%20Store%20%26%20Config%20--%3E%20Composer%0A%20%20%20%20Composer%20--%3E%20Room%20--%3E%20Check%20--%3E%20Card%0A"}),e[3]||(e[3]=h('<h2 id="designing-a-template" tabindex="-1">Designing a template <a class="header-anchor" href="#designing-a-template" aria-label="Permalink to &quot;Designing a template&quot;">​</a></h2><p>A template is a JSON Schema document, filled in with React JSON Schema Form, as in the earlier War Rooms. In the admin&#39;s <strong>Templates</strong> section, the admin either builds it from a palette of fields, dragging them into place or reordering them with the keyboard, or edits the JSON Schema directly in a code editor. Both edit the same template, and switching between them keeps it. Each field has its own settings: label, whether it is required, limits, options, and for pickers which forces or roles they offer.</p><p>The fields are:</p><table tabindex="0"><thead><tr><th>Field</th><th>What the player sees</th></tr></thead><tbody><tr><td>Text, long text</td><td>A text box, with a count of characters left</td></tr><tr><td>Number, slider</td><td>A number box, or a slider with a number box beside it for the keyboard</td></tr><tr><td>Yes/no</td><td>A tick box; left unticked, it is sent as &quot;no&quot;</td></tr><tr><td>Date, date and time</td><td>The browser&#39;s date picker; shown in each reader&#39;s local time</td></tr><tr><td>Drop-down</td><td>A list of fixed options</td></tr><tr><td>Linked drop-downs</td><td>The choice in one list sets the options of the next</td></tr><tr><td>Force picker, role picker</td><td>A list of the game&#39;s forces or roles, or only those in this room. The message stores the force&#39;s or role&#39;s id, so each card shows its current name, and a deleted one&#39;s last name marked &quot;(deleted)&quot;</td></tr></tbody></table><p>Templates use a deliberately small part of JSON Schema: named fields of simple types, conditions one level deep, and a short list of display options. Anything outside it is refused, with a message saying where and why. That keeps every template something the builder can show, a card can display, and every client can check quickly.</p><p>Beside the editor, a <strong>live preview</strong> shows the form exactly as players will see it: the same widgets, the same theme and the same checks. Pressing <strong>Check</strong> shows what a player would be told before sending.</p><h2 id="choosing-who-may-use-it" tabindex="-1">Choosing who may use it <a class="header-anchor" href="#choosing-who-may-use-it" aria-label="Permalink to &quot;Choosing who may use it&quot;">​</a></h2><p>Each chat room&#39;s settings say whether free text is allowed, and which templates each force or role may use there. Forces in the same room can have different templates. A role&#39;s own entry adds to its force&#39;s. The umpire, and White Force roles who are not observers, may use every template the room offers; observers never post. The access table in the admin shows each role&#39;s templates in each room before anything is published.</p><h2 id="publishing-and-locking" tabindex="-1">Publishing and locking <a class="header-anchor" href="#publishing-and-locking" aria-label="Permalink to &quot;Publishing and locking&quot;">​</a></h2><p>Templates are published with the rest of the game. Once a published room has offered a template, players may have used it, so it is locked: its fields, their labels and order, and its name are fixed. The editor shows it read only, and publishing refuses a change to any of them. To change it, the admin copies it to a new template, edits the copy and offers the copy instead. Old messages keep showing with the template they were sent with. Only a locked template&#39;s description can still change.</p><h2 id="sending-and-reading" tabindex="-1">Sending and reading <a class="header-anchor" href="#sending-and-reading" aria-label="Permalink to &quot;Sending and reading&quot;">​</a></h2><p>When a room offers templates, the composer gets a <strong>Message type</strong> drop-down: free text, if the room allows it, and each template the player&#39;s role may use. When Send is pressed, any field that does not fit is marked with the reason, and nothing is sent until every field fits. Values not yet sent are kept if the player switches between types or the message is refused, as unsent text is. In a room that takes only templates and offers a role none, the composer says so.</p><p>Like the plain text box, the composer can be collapsed to a slim bar at the foot of the room, for players who read a room but rarely write in it. Collapsing loses nothing: the chosen type and the form&#39;s values are kept, and the bar says <strong>Draft not sent</strong> while something is waiting. Each room remembers whether it was collapsed, with the rest of the player&#39;s layout.</p><p>Recipients see a card: the template&#39;s name, then each filled field&#39;s label and value, in the form&#39;s order. Everything on a card is plain text.</p><p>Every client checks every templated message against its template when it shows it:</p><ul><li>A message that fits, from a role the room offers the template to, is a card.</li><li>A message whose template the room no longer offers to its sender, for example after the admin changed the room&#39;s settings, is still a card, with a note saying so. History does not change when the settings do.</li><li>A message that does not fit its template, or names a template the game does not have, is shown as plain text, field by field, with a warning.</li></ul><p>The check takes a few hundredths of a millisecond per message, and a room of 2,000 templated messages opens and scrolls as quickly as a plain chat room.</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><p>In the demo below, log in as <code>blue-co</code> (Blue CO) and open the <strong>Blue Reports</strong> room, which takes templates only. Its three templates use every field type. Log in as <code>admin</code> and open <code>#/admin</code> to see the Templates section and the preview; the demo logins are listed on the welcome page.</p>',19)),s(r,{height:480})])}const A=i(m,[["render",p]]);export{b as __pageData,A as default};
